#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 15

static long heap[CAPACITY];
static int size = 0;

static void heap_swap(int i, int j) {
    long tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

static void heapify_up(int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent] <= heap[idx]) break;
        heap_swap(parent, idx);
        idx = parent;
    }
}

static void heapify_down(int idx) {
    while (1) {
        int left = idx * 2 + 1;
        int right = left + 1;
        int smallest = idx;
        if (left < size && heap[left] < heap[smallest]) smallest = left;
        if (right < size && heap[right] < heap[smallest]) smallest = right;
        if (smallest == idx) break;
        heap_swap(idx, smallest);
        idx = smallest;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];
        if (cmd[0] == 'I') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);
            if (endptr == cmd + 1 || *endptr != '\0') {
                puts("ERR");
                continue;
            }
            if (size >= CAPACITY) {
                puts("FULL");
                continue;
            }
            heap[size] = val;
            heapify_up(size);
            ++size;
            printf("INS %ld\n", val);
        } else if (strcmp(cmd, "X") == 0) {
            if (size == 0) {
                puts("EMPTY");
                continue;
            }
            long min = heap[0];
            heap[0] = heap[size - 1];
            --size;
            heapify_down(0);
            printf("MIN %ld\n", min);
        } else {
            puts("ERR");
        }
    }
    return 0;
}
}
